import{_ as t,o,c as a,a6 as n}from"./chunks/framework.BJFjZBwW.js";const l=JSON.parse('{"title":"Sensors","description":"","frontmatter":{},"headers":[],"relativePath":"use/sensors.md","filePath":"use/sensors.md","lastUpdated":1704468805000}'),s={name:"use/sensors.md"};function u(i,e,h,r,d,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h1><p>Subscribe to all the messages with mosquitto or open your MQTT client software:</p><p><code> sudo mosquitto_sub -t +/# -v</code></p><h3 id="adc" tabindex="-1">ADC <a class="header-anchor" href="#adc" aria-label="Permalink to &quot;ADC&quot;">​</a></h3><p>The value is between 0 and 1024 and is transmitted via MQTT when it changes. <code>home/OpenMQTTGateway/ADCtoMQTT {&quot;value&quot;:543}</code></p><h3 id="dht" tabindex="-1">DHT <a class="header-anchor" href="#dht" aria-label="Permalink to &quot;DHT&quot;">​</a></h3><p>You will receive every TimeBetweenReadingDHT (set into config_DHT.h) the DHT measurement (30s per default).</p><p><code>home/OpenMQTTGateway/DHTtoMQTT {&quot;tempc&quot;:21,&quot;tempf&quot;:69.8,&quot;hum&quot;:51}</code></p><p>If you want to don&#39;t resend value when it is the same you can set dht_always = false in config_DHT.h</p><h3 id="htu21" tabindex="-1">HTU21 <a class="header-anchor" href="#htu21" aria-label="Permalink to &quot;HTU21&quot;">​</a></h3><p>You will receive the HTU21 sensor readings every TimeBetweenReadinghtu21 (set into config_HTU21.h) (30s by default).</p><p><code>home/OpenMQTTGateway/CLIMAtoMQTT/htu {&quot;tempc&quot;:25.34064,&quot;tempf&quot;:77.61314,&quot;hum&quot;:56.53052}</code></p><p>If you don&#39;t want to resend values that haven&#39;t changed you can set htu21_always = false in config_HTU21.h</p><h3 id="ahtx0-aht10-and-aht20" tabindex="-1">AHTx0 (AHT10 and AHT20) <a class="header-anchor" href="#ahtx0-aht10-and-aht20" aria-label="Permalink to &quot;AHTx0 (AHT10 and AHT20)&quot;">​</a></h3><p>You will receive the AHT sensor readings every TimeBetweenReadingAHTx0 (set into config_AHTx0.h) (30s by default).</p><p><code>home/OpenMQTTGateway/CLIMAtoMQTT/aht { &quot;tempc&quot;: 27.48108, &quot;tempf&quot;: 81.46594, &quot;hum&quot;: 48.90614 }</code></p><p>If you don&#39;t want to resend values that haven&#39;t changed you can set AHTx0_always = false in config_AHTx0.h</p><h3 id="ds18x20" tabindex="-1">DS18x20 <a class="header-anchor" href="#ds18x20" aria-label="Permalink to &quot;DS18x20&quot;">​</a></h3><p>You will receive the DS18x20 sensor readings every DS1820_INTERVAL_SEC (set into config_DS1820.h) (60s by default). Each sensor will be published under the following topic using each sensors&#39; address.</p><p><code>home/OpenMQTTGateway/CLIMAtoMQTT/ds1820/0x0000000000000000 {&quot;tempc&quot;:27.8, &quot;tempf&quot;:82.04, &quot;type&quot;:&quot;DS18B20&quot;,&quot;res&quot;:&quot;12bit\\n&quot;,&quot;addr&quot;:&quot;0x28616411907650bc&quot;}</code></p><p>The units for temperature readings are sent in Celsius by default can be changed to Fahrenheit by setting DS1820_FAHRENHEIT = true in in config_DS1820.h</p><p>If you don&#39;t want to resend values that haven&#39;t changed you can set DS1820_ALWAYS = false in config_DS1820.h</p><h3 id="hcsr501" tabindex="-1">HCSR501 <a class="header-anchor" href="#hcsr501" aria-label="Permalink to &quot;HCSR501&quot;">​</a></h3><p>A boolean value of the PIR sensors state is sent when a state change occurs. The length of time that the PIR stays in a triggered state depends on the PIR hardware and is not changed by OpenMQTTGateway.</p><p><code>home/OpenMQTTGateway/HCSR501toMQTT {&quot;presence&quot;:&quot;false&quot;}</code></p><p>You can have another PIN mirror the value of the PIR sensor output by adding the following to config_HCSR501.h This can be useful if you would like to connect an LED to turn on when motion is detected.</p><p><code>#define HCSR501_LED_NOTIFY_GPIO 4</code></p><p>This notification pin can be inverted if driving directly or through a transistor/mosfet. <code>#define INVERT_LED_NOTIFY true</code></p><h3 id="rn8209" tabindex="-1">RN8209 <a class="header-anchor" href="#rn8209" aria-label="Permalink to &quot;RN8209&quot;">​</a></h3><p>You will receive every <code>TimeBetweenPublishingRN8209</code> (set into config_RN8209.h) the RN8209 measurements (every 60s per default), or if the difference between the previous current reading and the new reading is more than 0.1A, or if the difference between the previous voltage reading and the new reading is more than 2V. One reading is done every 0.5s.</p><p><code>home/OpenMQTTGateway/RN8209toMQTT {&quot;volt&quot;:120.34,&quot;current&quot;:7.92,&quot;power&quot;:954.61}</code></p><h3 id="touch" tabindex="-1">Touch <a class="header-anchor" href="#touch" aria-label="Permalink to &quot;Touch&quot;">​</a></h3><p>This sensor is only for ESP32, using the touch sensing peripheral. Up to 10 touch buttons can be defined, linked to 10 ESP32 pins that support touch sensing (GPIOs 0, 2, 4, 12, 13, 14, 15, 27, 32, 33) by defining TOUCH_GPIO, or TOUCH_GPIO_0 through TOUCH_GPIO_9. For example:</p><p><code>#define TOUCH_GPIO 4</code></p><p>The default is one sensor on GPIO 4.</p><p>When a touch is detected, a message is sent indicating the number of the button (&quot;id&quot;), the fact that a touch button was pressed (&quot;on&quot; is 1) and the value measured by the esp32 (&quot;value&quot;).</p><p><code>home/OpenMQTTGateway/touchToMQTT {&quot;id&quot;:0,&quot;on&quot;:1,&quot;value&quot;:10}</code></p><p>When the button stops being touched (e.g., the finger is lifted off the button), a message is sent indicating that the button was released (&quot;on&quot; is 0), as well as the duration of the button press in milliseconds (&quot;onDuration&quot;).</p><p><code>home/OpenMQTTGateway/touchToMQTT {&quot;id&quot;:0,&quot;on&quot;:0,&quot;value&quot;:70,&quot;onDuration&quot;:320}</code></p>',39)])])}const T=t(s,[["render",u]]);export{l as __pageData,T as default};
